// Background push handler. Runs in its own service worker scope, separate
// from the app-shell service worker generated by vite-plugin-pwa (sw.js) —
// Firebase's messaging SDK registers this one itself when getToken() is
// called with `serviceWorkerRegistration` pointing at it.
//
// IMPORTANT: this file is a plain static asset (Vite copies public/ files
// verbatim, it does not bundle them), so it can't import from
// src/lib/firebaseConfig.ts. Keep the values below in sync with that file
// by hand whenever you fill in your real Firebase project config.

importScripts("https://www.gstatic.com/firebasejs/11.0.2/firebase-app-compat.js");
importScripts("https://www.gstatic.com/firebasejs/11.0.2/firebase-messaging-compat.js");

firebase.initializeApp({
  apiKey: "REPLACE_ME",
  authDomain: "REPLACE_ME.firebaseapp.com",
  projectId: "REPLACE_ME",
  storageBucket: "REPLACE_ME.appspot.com",
  messagingSenderId: "REPLACE_ME",
  appId: "REPLACE_ME",
});

const messaging = firebase.messaging();

// The app icon chosen in Settings, as src/lib/appIcon.ts stores it for the
// app-shell worker too (public/app-icon-sw.js) — Cache Storage is shared by
// every service worker on the origin.
async function appIconUrl() {
  let id = "default";
  try {
    const hit = await (await caches.open("wallet-app-icon")).match("/__app-icon");
    if (hit) id = (await hit.text()).trim();
  } catch {
    // Cache Storage unavailable — use the default.
  }
  if (!["default", "dark", "clear", "tinted", "dark-red", "tinted-red"].includes(id)) id = "default";
  return `/app-icons/${id}/icon-192.png`;
}

// The backend sends data-only messages (backend/app/firebase.py); the
// notification fallback covers anything sent with a notification payload.
messaging.onBackgroundMessage(async (payload) => {
  const title = payload.data?.title ?? payload.notification?.title ?? "کیف پول";
  const body = payload.data?.body ?? payload.notification?.body ?? "";
  await self.registration.showNotification(title, {
    body,
    icon: await appIconUrl(),
    dir: "rtl",
  });
});
